export const useWindowSize = () => {
  const [size, setSize] = useState(window.innerWidth);
  useEffect(() => {
    const handle = () => setSize(window.innerWidth);
    window.addEventListener('resize', handle);
    return () => window.removeEventListener('resize', handle);
  }, []);
  return size;
};

